def read(p): return json.loads((ROOT/p).read_text(encoding='utf-8-sig'))
def rows(p): return list(csv.DictReader((ROOT/p).open(encoding='utf-8-sig',newline='')))
def write(p,d): p.write_bytes((json.dumps(d,indent=2,ensure_ascii=False)+'\n').encode('utf-8'))
def table(name,header,data):
 s=io.StringIO(newline='');w=csv.writer(s,lineterminator='\n');w.writerow(header);w.writerows(data)
 p=OUT/(name+'.csv');p.write_bytes(s.getvalue().encode());return str(p)
def fig(name):
 p=OUT/(name+'.png');plt.savefig(p,dpi=190,bbox_inches='tight',facecolor='white');plt.close();return str(p)
