def P(s):return {'kind':'p','text':s}
def H(s):return {'kind':'h','text':s}
def T(path,caption):return {'kind':'table','path':path,'caption':caption}
def F(path,caption):return {'kind':'figure','path':path,'caption':caption}
pages=[]
def page(title,*blocks):pages.append({'title':title,'blocks':list(blocks)})
